new_products as (
  insert into public.products
    (user_id, kind, name, name_key, maker, maker_address, region, country, category, abv, polish_ratio, sake_meter, acidity,
     ingredient, price_yen, price_note, ai_filled_fields, sources)
  select me.id, 'sake', v.name, v.name_key, v.maker, v.maker_address, v.region, 'Japan', v.category,
         v.abv::numeric, v.polish_ratio::integer, v.sake_meter::numeric, v.acidity::numeric,
         v.ingredient, v.price_yen::integer, v.price_note, v.ai_filled_fields::text[], v.sources::jsonb
  from v cross join me
  on conflict (user_id, kind, name_key) do nothing
  returning id, user_id, name_key
)
insert into public.tastings (user_id, product_id, status, drunk_on, rating, served, sweet_dry, comment)
select p.user_id, p.id, 'saved', v.drunk_on::date, v.rating::numeric, v.served, v.sweet_dry::smallint, v.comment
from new_products p join v on v.name_key = p.name_key
returning drunk_on, rating, served, comment;

